local CHS = game:GetService("ChangeHistoryService") CHS:SetWaypoint("vor HBBUpdate") local root = workspace:FindFirstChild("HBBUpdate") if not root then warn("HBBUpdate: Ordner 'HBBUpdate' nicht im Workspace - erst die .rbxmx importieren") return end local targets = { ReplicatedStorage = game:GetService("ReplicatedStorage"), ServerScriptService = game:GetService("ServerScriptService"), StarterPlayerScripts = game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts") } local replaced, created = 0, 0 local function walk(src, dst, path) for _, child in src:GetChildren() do local here = path .. "/" .. child.Name if child:IsA("LuaSourceContainer") then local existing = dst:FindFirstChild(child.Name) if existing and existing:IsA("LuaSourceContainer") then if existing.ClassName ~= child.ClassName then warn("HBBUpdate: andere Skript-Art in Studio, nur Quelltext ersetzt:", here, existing.ClassName, "->", child.ClassName) end existing.Source = child.Source replaced += 1 else child:Clone().Parent = dst created += 1 print("HBBUpdate: neu angelegt", here) end elseif child:IsA("Folder") then local folder = dst:FindFirstChild(child.Name) if not folder then folder = Instance.new("Folder") folder.Name = child.Name folder.Parent = dst print("HBBUpdate: Ordner angelegt", here) end walk(child, folder, here) end end end for name, service in targets do local part = root:FindFirstChild(name) if part then walk(part, service, name) end end root:Destroy() CHS:SetWaypoint("HBBUpdate eingespielt") print(("HBBUpdate: %d Skripte ersetzt, %d neu angelegt, nichts geloescht"):format(replaced, created))
